// ---------------------------------------------------------------------------
// font_rom.v -- 8x16 ASCII glyph ROM for the InstRec UI (M3)
//
// 95 printable characters (0x20..0x7E), 16 scanlines each, MSB = leftmost
// pixel. The hex file is generated by scripts/gen_font_hex.py.
// Synchronous read (pix domain): present the address, get the row one cycle
// later, matching the other UI lookup tables.
// ---------------------------------------------------------------------------

module font_rom (
    input  wire       pix_clk,
    input  wire [7:0] char_code,
    input  wire [3:0] row,
    output reg  [7:0] bits
);

    reg [7:0] rom [0:1519];

    initial begin
        $readmemh("src/ui/font8x16.hex", rom);
    end

    wire [7:0]  code_idx = (char_code < 8'd32)  ? 8'd32  :
                           (char_code > 8'd126) ? 8'd126 : char_code;
    wire [10:0] addr = (code_idx - 8'd32) * 16 + {7'd0, row};

    always @(posedge pix_clk) begin
        bits <= rom[addr];
    end

endmodule